import pandas as pd

def compute_signal(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy().sort_values(["permno", "time_avail_m"])
    prior_sales = df.groupby("permno")["sale"].shift(1)
    df["sales_growth"] = df["sale"] / prior_sales - 1
    df.loc[prior_sales == 0, "sales_growth"] = float("nan")

    df["growth_rank"] = df.groupby("time_avail_m")["sales_growth"].rank(
        method="average"
    )

    rank_lags = [df.groupby("permno")["growth_rank"].shift(i) for i in range(5)]
    df["signal"] = sum(
        weight * rank_lag
        for weight, rank_lag in zip([5, 4, 3, 2, 1], rank_lags)
    ) / 15

    df = df[df["signal"].notna() & df["signal"].map(lambda x: float("-inf") < x < float("inf"))]
    return df[["permno", "time_avail_m", "signal"]].rename(
        columns={"time_avail_m": "yyyymm"}
    )
